  const porque = t => { const r = []; if (t.status === "bloqueada") r.push("bloqueada"); const dr = C.R[t.id]?.drv && T.find(x => x.id === C.R[t.id].drv); if (dr) r.push(`dependia de ${dr.cod}`); const h = (t.hist || []).filter(x => x.depois?.prazo); if (h.length) r.push(`prazo já adiado ${plural(h.length, "vez", "vezes")}`); const c = ckCarga(t.resp); if (c.st === "crit") r.push(`${ckMN(t.resp)} com ${pct(c.load)} de carga`); if (!t.esforco) r.push("sem estimativa de esforço"); return r.join("; ") || "sem causa registrada"; };
