  const prox = {}; for (const t of T.filter(t => ckOpen(t) && ((t.prazo >= nws && t.prazo <= nwe) || (C.R[t.id]?.es >= nws && C.R[t.id]?.es <= nwe)))) (prox[ckMN(t.resp)] ||= []).push({ cod: t.cod, id: t.id, titulo: t.titulo, prazo: t.prazo });
