    riscos_top: ckA("ckRisk").filter(r => !["fechado", "mitigado"].includes(r.status)).sort((a, b) => ckRiscoScore(b) - ckRiscoScore(a)).slice(0, 5).map(r => ({ cod: r.cod, desc: r.desc, score: ckRiscoScore(r), mitigacao: r.mitig, dono: ckMN(r.dono) })), riscos_novos: ckA("ckRisk").filter(r => inM(r.criado)).length,
