  L.push(`# Rapporto mensile — ${ckMeseIT(mk)}`, "", `**Redatto da:** ${p.nome || "—"}${p.funcoes ? ` · ${p.funcoes}` : ""}  `, `**Data:** ${ckDIT(TODAY)}`, "", "## 1. Sintesi");
