  L.push("## 2. Avanzamento per progetto", "", "| Progetto | Fase | Completate | Aperte | Fine prevista | Attività critiche |", "|---|---|---|---|---|---|", ...D.projetos.map(x => `| ${x.nome}${x.cliente ? ` (${x.cliente})` : ""} | ${x.fase} | ${x.concluidas} | ${x.abertas} | ${ckDIT(x.fim_previsto)} | ${x.criticas.join(", ") || "—"} |`), "");
  L.push("## 3. Scadenze e milestone", ...(D.marcos_mes.length ? D.marcos_mes.map(m => `- ${ckDIT(m.data)} — ${m.nome} (${m.tipo || "milestone"}, ${m.projeto}): ${m.cumprido ? "rispettata" : "non ancora chiusa"}`) : ["- Nessuna milestone nel mese."]), ...(D.proximos_marcos.length ? ["", "Prossime milestone:", ...D.proximos_marcos.map(m => `- ${ckDIT(m.data)} — ${m.nome} (${m.projeto})`)] : []), "");
  L.push("## 4. Rischi principali", ...(D.riscos_top.length ? D.riscos_top.map(r => `- **${r.cod}** ${r.desc} — punteggio ${r.score}/25; responsabile: ${r.dono}; mitigazione: ${r.mitigacao || "da definire"}`) : ["- Nessun rischio aperto."]), "");
  L.push("## 5. Problemi aperti e decisioni", ...(D.problemas_abertos.length ? D.problemas_abertos.map(x => `- **${x.cod}** ${x.titulo} (gravità ${({ alta: "alta", média: "media", baixa: "bassa" })[x.sev] || x.sev}; stato: ${({ aberto: "aperto", "em análise": "in analisi", "solução escolhida": "soluzione scelta" })[x.status] || x.status})`) : ["- Nessun problema aperto."]), ...(D.decisoes.length ? ["", "Decisioni tecniche del mese:", ...D.decisoes.map(d => `- **${d.cod}** ${d.titulo}${d.norma ? ` (rif. ${d.norma})` : ""}`)] : []), "");
  L.push("## 6. Elaborati e BIM", `- Elaborati emessi nel mese: ${D.elaborati.emessi} (approvati: ${D.elaborati.approvati}); in ritardo: ${D.elaborati.in_ritardo.length ? D.elaborati.in_ritardo.join("; ") : "nessuno"}.`, `- Clash aperti all'ultima verifica: ${D.bim.clash_aperti}; consegne IFC nel mese: ${D.bim.ifc_consegnate}.`, ...(D.bim.modelli.length ? [`- Stato dei modelli: ${D.bim.modelli.join("; ")}.`] : []), "");
