  L.push("## 8. Prossimi passi", ...(D.vencidas.length ? [`- Recuperare le attività scadute: ${D.vencidas.slice(0, 5).join("; ")}.`] : []), ...ckAlertas().filter(a => a.st === "crit").slice(0, 4).map(a => `- Verificare: ${a.txt}`), "- Prossimo aggiornamento a fine mese.");
