function ckChange3(t) {
  if (t.id === "ck_gproj") { CK.gproj = t.value; render(); return true; }
  if (t.id === "ck_relmes") { CK.relMes = t.value || mkey(TODAY); render(); return true; }
  if (t.id === "ck_comt") { CK.com.tipo = t.value; render(); return true; }
  if (t.id === "ck_comp") { CK.com.proj = t.value; return true; }
  if (t.dataset.ckelst) { const e = ckA("ckEl").find(x => x.id === t.dataset.ckelst); if (e) { e.stato = t.value; if (["emesso", "approvato"].includes(t.value) && !e.emissao) e.emissao = TODAY; touch("ckEl", { label: `${e.codigo || e.cod}: ${t.value}` }); } return true; }
  return false;
}

